        return Request(
            id = requestId,
            description = "RUM Request",
            url = buildUrl(context, executionContext),
            headers = buildHeaders(
                requestId,
                idempotencyKey,
                context
            ),
            body = body,
            contentType = RequestFactory.CONTENT_TYPE_TEXT_UTF8
        )
    }

