        val queryParams = buildMap {
            put(RequestFactory.QUERY_PARAM_SOURCE, context.source)

            val tags = buildTags(executionContext)
            if (tags.isNotEmpty()) {
                put(RequestFactory.QUERY_PARAM_TAGS, tags)
